llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Saccharin showed absolute oral bioavailability of 0.80±0.05 in fed human volunteers versus i.v., a direct high-F measurement in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Meperidine/pethidine had absolute oral bioavailability of 0.61 in healthy volunteers versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Ampicillin absolute oral bioavailability was 61.8±17.3% in humans, supporting high F despite incomplete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Praziquantel oral bioavailability was 27.2±5.4% even in patients with hepatic impairment, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Thalidomide, a poorly soluble neutral drug, had estimated oral bioavailability of 80-100% in humans, supporting high F for a similarly challenging neutral compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Imipramine-N-oxide, a tricyclic compound, showed 100% systemic availability after oral dosing in healthy volunteers, supporting high F for the tricyclic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Tolfenamic acid absolute oral bioavailability averaged 60% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Isoniazid oral bioavailability was 91.4% in tuberculosis patients, strongly supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental evidence from diverse small-molecule drugs in humans reports absolute oral bioavailability well above 20% (approximately 27-100%), with no contradictory evidence. The physicochemical prior is also favorable for absorption and permeability, and the low-solubility concern is not sufficient to lower F below 20% given the strong experimental support.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself was provided; all evidence is from high-transfer analogues.",
    "The query's low aqueous solubility could in principle limit absorption, but the high-transfer evidence from similarly challenging neutral compounds suggests F remains above 20%.",
    "No human data for the exact carbamazepine structure were included in the supplied evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

